#!/usr/bin/env node
/**
 * Composing `store/zapstore/zapstore.yaml` from the copy that already exists.
 *
 * Zapstore's config carries a name, a summary, a description and release notes
 * — all of which are already written, in `store/play` and `store/appstore`,
 * and reviewed there. Hand-writing them a third time is how a listing ends up
 * saying three different things about the same app.
 *
 * So this file is generated and the text files are the source. The structural
 * fields — where the code is, which asset to take, the licence — live in the
 * generator, because they are facts about the repository rather than copy.
 *
 *   node scripts/make-zapstore-config.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const read = (relative) =>
  readFileSync(path.join(root, relative), 'utf8').trim();

const REPOSITORY = 'https://github.com/fastpool/signer-guide';
const WEBSITE = 'https://signer-guide.fastpool.org';
const LICENSE = 'MIT';

/**
 * Where the APK comes from.
 *
 * The repository's releases rather than a local path, so that what Zapstore
 * publishes is the artefact anyone else can download and hash for themselves.
 * `zsp` takes a local file too, which is what a first publish from a laptop
 * uses — see `store/README.md`.
 */
const RELEASE_SOURCE = REPOSITORY;

/** What somebody would type to find this, not what the app calls itself. */
const TAGS = ['bitcoin', 'stacks', 'stx', 'staking', 'sbtc', 'wallet', 'defi'];

const SCREENSHOTS = [
  '01-welcome',
  '02-start',
  '03-your-stake',
  '04-contracts',
  '05-pools',
  '06-payouts',
  '07-the-data',
  '08-preferences',
];

/**
 * A YAML double-quoted scalar.
 *
 * The summary is "Bitcoin staking for STX: lock in your own wallet…", and a
 * bare colon-space in YAML is a mapping — so an unquoted summary is not a
 * parse error somewhere obvious, it is a config that means something else.
 */
function quoted(text) {
  return `"${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

/** A YAML block scalar, indented under its key. */
function block(text, indent = '  ') {
  return text
    .split('\n')
    .map((line) => (line.length === 0 ? '' : indent + line))
    .join('\n');
}

const config = `# Generated by scripts/make-zapstore-config.mjs — do not edit by hand.
#
# The name, summary, description and release notes come from the same files the
# Play and App Store listings are built from, so the three cannot drift. The
# fields below them are facts about this repository rather than copy, and are
# edited in the generator.
#
# Publish with:
#
#   SIGN_WITH="bunker://…" zsp publish store/zapstore/zapstore.yaml --skip-metadata
#
# \`--skip-metadata\` matters: without it zsp fetches metadata from the Play
# Store and the repository and overwrites what is written here.

repository: ${quoted(REPOSITORY)}
release_source: ${quoted(RELEASE_SOURCE)}
# One APK per release, built arm64-only — see ../../README.md.
match: ".*\\\\.apk$"

name: "Signer Guide"
summary: ${quoted(read('store/play/en-US/short_description.txt'))}
description: |
${block(read('store/play/en-US/full_description.txt'))}

license: ${quoted(LICENSE)}
website: ${quoted(WEBSITE)}
tags: [${TAGS.join(', ')}]

icon: ../../assets/icon.png
images:
${SCREENSHOTS.map((name) => `  - ../screenshots/raw/${name}.png`).join('\n')}

release_notes: |
${block(read('store/play/en-US/changelogs/default.txt'))}
`;

const target = path.join(root, 'store/zapstore/zapstore.yaml');
writeFileSync(target, config);
console.log(`wrote ${path.relative(process.cwd(), target)}`);
